```python
# schemas.py
from datetime import datetime
from uuid import UUID

from ninja import Schema


class ProblemDetailSchema(Schema):
    type: str = "about:blank"
    title: str
    status: int
    detail: str | None = None
    instance: str | None = None


class ItemCreateSchema(Schema):
    name: str
    description: str | None = None

    def to_command(self) -> dict[str, object]:
        return {
            "name": self.name,
            "description": self.description,
        }


class ItemUpdateSchema(Schema):
    name: str | None = None
    description: str | None = None

    def to_command(self) -> dict[str, object]:
        return self.dict(exclude_unset=True)


class ItemListSchema(Schema):
    id: UUID
    name: str
    created_at: datetime


class ItemDetailSchema(Schema):
    id: UUID
    name: str
    description: str | None
    created_at: datetime
    updated_at: datetime

    @classmethod
    def from_domain(cls, item) -> "ItemDetailSchema":
        return cls(
            id=item.id,
            name=item.name,
            description=item.description,
            created_at=item.created_at,
            updated_at=item.updated_at,
        )
```

```python
# routers.py
from uuid import UUID

from ninja import Router

from .schemas import (
    ItemCreateSchema,
    ItemDetailSchema,
    ItemListSchema,
    ItemUpdateSchema,
    ProblemDetailSchema,
)
from .services import create_item, delete_item, get_item, list_items, update_item

router = Router(tags=["items"])


def not_found_problem(detail: str) -> ProblemDetailSchema:
    return ProblemDetailSchema(
        title="Not Found",
        status=404,
        detail=detail,
    )


@router.get("/", response=list[ItemListSchema])
def item_list(request):
    items = list_items(actor=request.auth)
    return [
        ItemListSchema(
            id=item.id,
            name=item.name,
            created_at=item.created_at,
        )
        for item in items
    ]


@router.post("/", response={201: ItemDetailSchema, 409: ProblemDetailSchema})
def item_create(request, payload: ItemCreateSchema):
    item = create_item(command=payload.to_command(), actor=request.auth)
    return 201, ItemDetailSchema.from_domain(item)


@router.get("/{item_id}", response={200: ItemDetailSchema, 404: ProblemDetailSchema})
def item_detail(request, item_id: UUID):
    item = get_item(item_id=item_id, actor=request.auth)
    if item is None:
        return 404, not_found_problem("Item does not exist.")
    return ItemDetailSchema.from_domain(item)


@router.patch("/{item_id}", response={200: ItemDetailSchema, 404: ProblemDetailSchema})
def item_update(request, item_id: UUID, payload: ItemUpdateSchema):
    item = update_item(
        item_id=item_id,
        command=payload.to_command(),
        actor=request.auth,
    )
    if item is None:
        return 404, not_found_problem("Item does not exist.")
    return ItemDetailSchema.from_domain(item)


@router.delete("/{item_id}", response={204: None, 404: ProblemDetailSchema})
def item_delete(request, item_id: UUID):
    deleted = delete_item(item_id=item_id, actor=request.auth)
    if not deleted:
        return 404, not_found_problem("Item does not exist.")
    return 204, None
```

```python
# api.py
from ninja import NinjaAPI

from .routers import router as items_router

api = NinjaAPI()
api.add_router("/items", items_router)
```

핵심 전제: Router는 request validation, auth 전달, service/usecase 호출, response mapping만 담당하고 business rule, transaction, ORM query는 `services.py` 쪽에 둡니다. `ModelSchema`를 쓰더라도 `fields`를 명시해서 공개 필드가 우연히 늘어나지 않게 해야 합니다.

